import React, { useEffect, useState } from 'react';
import { View, ScrollView, Pressable, Alert } from 'react-native';
import { useStore } from 'react-redux';
import { Text, Skeleton, Button } from '@rneui/themed';
import Icon from 'react-native-vector-icons/Ionicons';
import { getDevices } from '../apis/apis';
import SpaceLoading from './SpaceLoading';
import { Image } from '@rneui/base';
import { bookParking, getWallet } from '../apis/apis';
import { setWallet, setScope } from './../redux/reducer';

const ConfirmParking = (props) => {
    const store = useStore();
    const user = store.getState().app.user;
    const lables = store.getState().app.trans;
    const location = props.route.params.location;
    const bookingDate = props.route.params.bookingDate;
    const startTime = props.route.params.startTime;
    const endTime = props.route.params.endTime;
    const [level, setLevel] = useState();
    const [devices, setDevices] = useState([]);
    const [filtered, setFiltered] = useState([]);
    const [selectedDevice, setSelectedDevice] = useState({ id: '', name: '', level: '' });
    const [loading, setLoading] = useState(true);
    const [btnLoading, setBtnLoading] = useState(false);
    let blocks = [];
    let levels = [];
    if (location.multi_block === 1 && location.blocks !== null) {
        blocks = JSON.parse(location.blocks);
    }
    if (location.multi_storey === 1 && location.levels !== null) {
        levels = JSON.parse(location.levels);
    }
    const [activeBlock, setActiveBlock] = useState(blocks[0]);
    useEffect(() => {
        props.navigation.setOptions({
            headerTitle: lables['confirm_parking'],
            headerBackTitle: lables['back'],
            headerBackTitleVisible: false,
            headerShadowVisible: false,
            headerTintColor: '#FFF',
            headerStyle: {
                backgroundColor: '#28B4F2'
            },
            headerRight: () => {
                return (
                    <Pressable
                        onPress={() => {
                            props.navigation.navigate('Home')
                        }}
                    >
                        <Icon name='home' color="#FFF" size={26} style={{ marginHorizontal: 20, }} />
                    </Pressable>
                );
            }
        });
        let fData = {
            location: location.id,
            bookingDate: bookingDate,
            startTime: startTime,
            endTime: endTime

        }
        getDevices(fData)
            .then((res) => {
                if (res.code === 200) {
                    setDevices(res.data.data);
                    setFiltered(res.data.data);
                    setLoading(false);
                }
            })
            .catch((e) => {
                console.log(e);
            })
    }, []);

    return (
        <View
            style={{
                flex: 1,
                backgroundColor: '#FFF'
            }}
        >
            <ScrollView showsVerticalScrollIndicator={false}>
                <ScrollView horizontal>
                    {
                        blocks.map((item) => {
                            return (
                                <Pressable
                                    onPress={() => {
                                        setActiveBlock(item);
                                    }}
                                    key={item}
                                    style={{
                                        borderRadius: 5,
                                        borderColor: "#0095d5",
                                        backgroundColor: activeBlock === item ? "#eaf6ff" : '#FFF',
                                        padding: 5,
                                        paddingLeft: 15,
                                        paddingRight: 15,
                                        margin: 10,
                                        shadowColor: "#000",
                                        shadowOffset: {
                                            width: 0,
                                            height: 1,
                                        },
                                        shadowOpacity: 0.25,
                                        shadowRadius: 3.50,
                                        elevation: 2,
                                    }}
                                >
                                    <Text
                                        style={{
                                            fontWeight: 'bold',
                                            color: '#000'
                                        }}
                                    >{item}</Text>
                                </Pressable>
                            );
                        })
                    }
                </ScrollView>
                <ScrollView>
                    {
                        levels.map((level) => {
                            return (
                                <View
                                    key={level}
                                    style={{
                                        padding: 5,
                                        paddingLeft: 15,
                                        paddingRight: 15,
                                        margin: 10,
                                        shadowColor: "#000",
                                        shadowOffset: {
                                            width: 0,
                                            height: 1,
                                        },
                                        shadowOpacity: 0.25,
                                        shadowRadius: 3.50,
                                        elevation: 2,
                                        backgroundColor: '#FFF',
                                        borderRadius: 5,
                                    }}
                                >
                                    <Text
                                        style={{
                                            fontWeight: 'bold',
                                            textAlign: 'center',
                                            backgroundColor: '#eaf6ff',
                                            width: 100,
                                            alignSelf: 'center',
                                            shadowColor: "#000",
                                            shadowOffset: {
                                                width: 0,
                                                height: 1,
                                            },
                                            shadowOpacity: 0.25,
                                            shadowRadius: 3.50,
                                            elevation: 2,
                                            margin: 5,
                                        }}
                                    >{level}</Text>
                                    {
                                        loading &&
                                        <SpaceLoading />
                                    }
                                    {
                                        !loading &&
                                        <View
                                            style={{
                                                display: 'flex',
                                                flexDirection: 'row',
                                                flexWrap: 'wrap'
                                            }}
                                        >
                                            {
                                                filtered.map((d) => {
                                                    if (d.block === activeBlock && d.level === level) {
                                                        return (
                                                            <Pressable
                                                                onPress={() => {
                                                                    if (d.reserved === "no") {
                                                                        setLevel(level);
                                                                        setSelectedDevice(d);

                                                                    }
                                                                }}
                                                                style={{
                                                                    height: 75,
                                                                    width: 75,
                                                                    borderRadius: 5,
                                                                    alignItems: 'center',
                                                                    backgroundColor: d.reserved === "yes" ? '#CCC' : '#2196F3',
                                                                    justifyContent: 'center',
                                                                    alignSelf: 'center',
                                                                    display: 'flex',
                                                                    borderWidth: 1,
                                                                    margin: 4,
                                                                    borderColor: '#CCC',
                                                                    shadowColor: 'rgba(31, 38, 135, 0.37)',
                                                                    shadowOffset: { width: 0, height: 8 },
                                                                    shadowRadius: 32,
                                                                    shadowOpacity: 1,
                                                                    elevation: 8,
                                                                    borderRadius: 10,
                                                                    borderWidth: 1,
                                                                    borderColor: 'rgba(255, 255, 255, 0.18)',
                                                                    backdropFilter: 'blur(4px)',
                                                                }}
                                                            >
                                                                {
                                                                    selectedDevice.id === d.id &&
                                                                    <Icon name='checkmark-circle-outline' size={40} color="#FFF" />
                                                                }
                                                                {
                                                                    d.reserved === "yes" && d.occupied_status === "yes" &&
                                                                    <Icon name='car-sport-outline' size={35} color={"#FFFF"} />
                                                                }
                                                                {
                                                                    d.reserved === "yes" && d.occupied_status === "no" &&
                                                                    <Icon name='lock-closed-outline' size={35}></Icon>
                                                                }
                                                                {
                                                                    d.reserved === "no" &&
                                                                    <Text
                                                                        style={{
                                                                            color: '#FFF',
                                                                            fontWeight: 'bold',
                                                                            padding:5,
                                                                        }}
                                                                    >{d.device_name}</Text>
                                                                }
                                                            </Pressable>
                                                        );
                                                    } else {
                                                        return (
                                                            <></>
                                                        );
                                                    }

                                                })
                                            }
                                        </View>
                                    }


                                </View>
                            );
                        })
                    }
                </ScrollView>
                <Button
                    loading={btnLoading}
                    onPress={() => {
                        setBtnLoading(true);
                        let data = {
                            location: location.id,
                            block: activeBlock,
                            level: level,
                            start_time: startTime,
                            end_time: endTime,
                            hours: props.route.params.hours,
                            date: props.route.params.bookingDate,
                            device: selectedDevice.id,
                            user: user.id,
                            vehicle: props.route.params.vehicle.name,
                        };
                        bookParking(data)
                            .then((res) => {
                                console.log(res);
                                getWallet(user.id)
                                    .then((wres) => {
                                        store.dispatch(setWallet(wres.data.data));
                                        setBtnLoading(false);
                                        if (res.code === 200) {
                                            Alert.alert(lables['booking_confirmed'], lables['booking_confirmed_text']);
                                            props.navigation.navigate('Home')
                                        }
                                    })
                                    .catch(e => {
                                        Alert.alert(lables['booking_confirmed'], lables['booking_confirmed_text']);
                                        props.navigation.navigate('Home')
                                        console.log(e);
                                    })
                            })
                            .catch(e => {
                                setBtnLoading(false);
                                console.log(e);
                            })
                    }}
                    buttonStyle={{
                        borderRadius: 30,
                        margin: 10,
                    }}
                    title={lables['confirm']}
                />
            </ScrollView>
        </View>
    );
}

export default ConfirmParking;