import React, { useEffect } from 'react';
import { View, ScrollView, I18nManager, Image, Dimensions, Pressable } from 'react-native';
import { useStore } from 'react-redux';
import { Button, ListItem, Text } from '@rneui/themed';
import Icon from 'react-native-vector-icons/Ionicons';
const ViewLocation = (props) => {
    const store = useStore();
    const lables = store.getState().app.trans;
    const lang = I18nManager.isRTL ? 'ar' : 'en';
    const location = props.route.params.location;
    const slots = props.route.params.free_spots;
    const [hours, minutes, seconds] = location.start_time.split(':');
    const dateObj = new Date();
    dateObj.setHours(hours);
    dateObj.setMinutes(minutes);
    dateObj.setSeconds(seconds);
    const formattedStartTime = dateObj.toLocaleString('en-US', { hour: 'numeric', minute: 'numeric', hour12: true });
    const [chours, cminutes, cseconds] = location.close_time.split(':');
    const cdateObj = new Date();
    cdateObj.setHours(chours);
    cdateObj.setMinutes(cminutes);
    cdateObj.setSeconds(cseconds);
    const formattedCloseTime = cdateObj.toLocaleString('en-US', { hour: 'numeric', minute: 'numeric', hour12: true });
    useEffect(() => {
        props.navigation.setOptions({
            headerTitle: lang === "en" ? location.location_name : location.location_name_ar,
            headerBackTitle: lables['back'],
            headerBackTitleVisible:false,
            headerShadowVisible: false,
            headerTintColor: '#FFF',
            headerStyle: {
                backgroundColor: '#28B4F2'
            },
            headerRight: () => {
                return (
                    <Pressable
                        onPress={() => {
                            props.navigation.navigate('Home')
                        }}
                    >
                        <Icon name='home' size={26} color={'#FFF'} style={{ marginHorizontal: 20 }} />
                    </Pressable>
                );
            }
        });
    }, []);


    return (
        <View
            style={{
                flex: 1,
                backgroundColor: '#FFF'
            }}
        >
            <ScrollView>
                <View
                    style={{
                        marginTop: 30,
                        padding: 20,
                    }}
                >
                    <Image source={{ uri: location.location_image }}
                        style={{
                            width: Dimensions.get('screen').width - 40,
                            height: 200,
                            borderRadius: 10,
                        }}
                    />
                    <ListItem
                        containerStyle={{
                            padding: 0,
                            paddingTop: 15,
                        }}
                    >
                        <ListItem.Content>
                            <ListItem.Title
                                style={{
                                    fontWeight: 'bold',
                                    fontSize: 20,
                                    flexShrink: 1,
                                }}
                            >
                                {lang === "en" ? location.location_name : location.location_name_ar}
                            </ListItem.Title>
                            {
                                location.distance !== undefined &&
                                <ListItem.Subtitle>{location.distance + " KM"}</ListItem.Subtitle>
                            }

                        </ListItem.Content>
                        <Text
                            style={{
                                fontWeight: 'bold'
                            }}
                        >{formattedStartTime + ' - ' + formattedCloseTime}</Text>
                    </ListItem>
                    <Text
                        style={{
                            fontWeight: 'bold',
                            fontSize: 20,
                            marginTop: 10,
                        }}
                    ></Text>
                    <View
                        style={{
                            display: 'flex',
                            flexDirection: 'row',
                            justifyContent: 'space-around'
                        }}
                    >
                        <View
                            style={{
                                display: 'flex',
                                flexDirection: 'row',
                                borderWidth: 2,
                                borderRadius: 10,
                                borderColor: '#28B3F3',
                                paddingLeft: 5,
                                paddingRight: 5,
                                alignItems: 'center',
                            }}
                        >
                            <Icon name='location-outline' size={22} />
                            <Text
                                style={{
                                    fontSize: 18,
                                    fontWeight: 'bold',
                                    marginLeft: 4,
                                    marginRight: 4,
                                }}
                            >{slots} {lables['available']}</Text>
                        </View>
                        <View
                            style={{
                                display: 'flex',
                                flexDirection: 'row',
                                borderWidth: 2,
                                borderRadius: 10,
                                borderColor: '#28B3F3',
                                paddingLeft: 5,
                                paddingRight: 5,
                                alignItems: 'center',

                            }}
                        >
                            <Icon name='time-outline' size={22} />
                            <Text
                                style={{
                                    fontSize: 18,
                                    fontWeight: 'bold',
                                    marginLeft: 4,
                                    marginRight: 4,
                                }}
                            >{'KWD ' + location.hour_charge?.toFixed(3)}/hr</Text>
                        </View>
                    </View>
                    <Text
                        style={{
                            fontSize: 20,
                            fontWeight: '400'
                        }}
                    >{lables['description']}</Text>
                    <Text
                        style={{
                            color: '#9FA2A5'
                        }}
                    >{lang === "en" ? location.location_description : location.location_description_ar}</Text>
                    <Button
                        onPress={() => {
                            props.navigation.navigate('BookParking', location);
                        }}
                        title={lables['book_parking']}
                        buttonStyle={{
                            borderRadius: 40,
                        }}
                    />
                </View>
            </ScrollView>
        </View>
    );
}

export default ViewLocation;