import { ListItem, Text, Avatar, Button } from "@rneui/themed";
import React, { useEffect, useState } from "react";
import { View, ScrollView, I18nManager, Switch, ActivityIndicator, Linking, Pressable, ImageBackground } from 'react-native';
import { useStore } from "react-redux";
import Icon from 'react-native-vector-icons/Ionicons';
import BlinkLed from "./BlinkLed";
import { toggleLED, closeParkingBarrier } from './../apis/apis';
import ParkingGate from './ParkingGate';
const ViewParking = (props) => {
    const store = useStore();
    const lables = store.getState().app.trans;
    const parking = props.route.params;
    const lang = I18nManager.isRTL ? 'ar' : 'en';
    const [turnLed, setTurnLed] = useState(false);
    const [loading, setLoading] = useState(false);
    useEffect(() => {
        props.navigation.setOptions({
            headerTitle: lables['view_parking'],
            headerBackTitle: lables['back'],
            headerShadowVisible: false,
            headerTintColor: '#FFF',
            headerBackTitleVisible:false,
            headerStyle: {
                backgroundColor: '#28B4F2'
            },
            headerRight: () => {
                return (
                    <Icon name="home" size={24} color="#FFF"
                        style={{
                            padding: 10,
                        }}
                        onPress={() => {
                            props.navigation.navigate('Home')
                        }}
                    />
                );
            }
        });
    }, []);
    const handleParking = () => {
        if (!loading) {
            setLoading(true);
            closeParkingBarrier(parking.device_id)
                .then((res) => {
                    console.log(res.data);
                    setLoading(false);
                }).catch((e) => {
                    setLoading(false);
                })
        }
    }
    return (
        <View
            style={{
                flex: 1,
                backgroundColor: '#FFF',
                padding: 15,
            }}
        >
            <ScrollView>
                <View>
                    <ListItem
                        containerStyle={{
                            borderRadius: 5,
                            margin: 4,
                            elevation: 2,
                            shadowColor: "#000",
                            shadowOffset: {
                                width: 0,
                                height: 1,
                            },
                            shadowOpacity: 0.25,
                            shadowRadius: 3.50,
                        }}
                    >
                        <Avatar source={{ uri: parking.location_image }} />
                        <ListItem.Content>
                            <ListItem.Title>{lang === "en" ? parking.location_name : parking.location_name_ar}</ListItem.Title>
                        </ListItem.Content>
                    </ListItem>
                    <View
                        style={{
                            borderRadius: 5,
                            backgroundColor: '#FFF',
                            padding: 10,
                            margin: 4,
                            elevation: 2,
                            shadowColor: "#000",
                            shadowOffset: {
                                width: 0,
                                height: 1,
                            },
                            shadowOpacity: 0.25,
                            shadowRadius: 3.50,
                        }}
                    >
                        <Text
                            style={{
                                textAlign: 'center',
                                padding: 5,
                                fontWeight: 'bold'
                            }}
                        >{lables['parking_details']}</Text>
                        <ListItem containerStyle={{ padding: 2 }}>
                            <ListItem.Content>
                                <ListItem.Title>{lables['block']}</ListItem.Title>
                            </ListItem.Content>
                            <Text>{parking.block}</Text>
                        </ListItem>
                        <ListItem containerStyle={{ padding: 2 }}>
                            <ListItem.Content>
                                <ListItem.Title>{lables['level']}</ListItem.Title>
                            </ListItem.Content>
                            <Text>{parking.level}</Text>
                        </ListItem>
                        <ListItem containerStyle={{ padding: 2 }}>
                            <ListItem.Content>
                                <ListItem.Title>{lables['start_time']}</ListItem.Title>
                            </ListItem.Content>
                            <Text>{parking.start_time}</Text>
                        </ListItem>
                        <ListItem containerStyle={{ padding: 2 }}>
                            <ListItem.Content>
                                <ListItem.Title>{lables['parking_space']}</ListItem.Title>
                            </ListItem.Content>
                            <Text>{parking.device_name}</Text>
                        </ListItem>
                    </View>
                    {
                        new Date(parking.reservation_date).getDate() === new Date().getDate() &&
                        <View>
                            <ListItem
                                containerStyle={{
                                    borderWidth: 2,
                                    borderRadius: 10,
                                    marginTop: 20,
                                }}
                            >
                                <Icon name="sunny-outline" size={24} />
                                <ListItem.Content>
                                    <ListItem.Title>{lables['blink_led']}</ListItem.Title>
                                    {
                                        turnLed &&
                                        <BlinkLed />
                                    }

                                </ListItem.Content>
                                <Switch
                                    value={turnLed}
                                    onValueChange={() => {
                                        setTurnLed(!turnLed);
                                        toggleLED(parking.device_id)
                                            .then((res) => {
                                                console.log(res.data);
                                                setTimeout(() => {
                                                    setTurnLed(false);
                                                }, 5000)
                                            });

                                    }}
                                />
                            </ListItem>

                            <ImageBackground
                                source={require('./../assets/images/open.jpg')}
                                imageStyle={{
                                    borderRadius: 90,
                                    alignSelf: 'center',
                                }}
                                style={{
                                    marginTop: 20,
                                }}
                            >
                                <Button
                                    buttonStyle={{
                                        backgroundColor: 'transparent'
                                    }}
                                    loading={loading}
                                    onPress={() => {
                                        handleParking();
                                    }}
                                    style={{
                                        alignSelf: "center",
                                        padding: 10,
                                        display: 'flex',
                                        justifyContent: 'center'
                                    }}
                                >
                                    <Text
                                        style={{
                                            fontWeight: 'bold',
                                            color: '#FFF',
                                            fontSize: 20,
                                        }}
                                    >{lables['open_parking']}</Text>
                                </Button>
                            </ImageBackground>
                            <Button
                                buttonStyle={{
                                    marginTop: 10,
                                    borderRadius: 40,
                                    padding: 18,
                                }}
                                onPress={() => {
                                    var scheme = Platform.OS === 'ios' ? 'maps:' : 'geo:';
                                    var url = scheme + `${parking.latitude},${parking.longitude}`;
                                    Linking.openURL(url);
                                }}
                                title={lables['show_on_maps']}
                            />
                        </View>
                    }

                </View>
            </ScrollView>
        </View>
    );
}

export default ViewParking;
