import React, { useEffect, useState } from 'react';
import { View, ScrollView, StyleSheet, Dimensions, I18nManager } from 'react-native';
import { useStore } from 'react-redux';
import { getBrands, addVehicle } from './../apis/apis';
import { Input, ListItem, Dialog, Avatar, Button } from '@rneui/themed';
import Icon from 'react-native-vector-icons/Ionicons';
const AddVehicle = (props) => {
    const store = useStore();
    const lables = store.getState().app.trans;
    const user = store.getState().app.user;
    const lang = I18nManager.isRTL ? 'ar' : 'en';
    const [brand, setBrand] = useState({ id: '' });
    const [brands, setBrands] = useState([]);
    const [showDialog, setShowDialog] = useState(false);
    const [showCountryDialog, setShowCountryDialog] = useState(false);
    const [country, setCountry] = useState({
        name: 'Kuwait',
        name_ar: 'الكويت',
        code: 'KW',
    });
    const [loading, setLoading] = useState(false);
    const [plateCode, setPlateCode] = useState();
    const [plateNumber, setPlateNumber] = useState();
    const [name, setName] = useState();
    let countries = [
        {
            'name': 'Kuwait',
            'name_ar': 'الكويت',
            'code': 'KW',
        },
        {
            'name': 'United Arab Emirates',
            'name_ar': 'الإمارات العربية المتحدة',
            'code': 'UAE',
        },
        {
            'name': 'Bahrain',
            'name_ar': 'مملكة البحرين',
            'code': 'BB',
        },
        {
            'name': 'Saudi Arabia',
            'name_ar': 'المملكة العربية السعودية',
            'code': 'KSA',
        },
        {
            'name': 'Oman',
            'name_ar': 'سلطنة عمان',
            'code': 'SO',
        },
        {
            'name': 'Qatar',
            'name_ar': 'دولة قطر',
            'code': 'SQ',
        }
    ];
    useEffect(() => {
        props.navigation.setOptions({
            headerTitle: lables['add_vehicle'],
            headerBackTitle: lables['back'],
            headerBackTitleVisible:false,
            headerShadowVisible: false,
        });
        getBrands()
            .then((data) => {
                if (data.code === 200) {
                    setBrands(data.data);
                }
            })
            .catch(() => {
                setBrands([]);
            });
    }, []);
    return (
        <View
            style={{
                flex: 1,
                backgroundColor: '#FFF'
            }}
        >
            <ScrollView>
                <View
                    style={{
                        marginTop: '20%'
                    }}
                >
                    <ListItem
                        onPress={() => {
                            setShowCountryDialog(true);
                        }}
                        containerStyle={{
                            borderWidth: 1,
                            borderRadius: 10,
                            margin: 10,
                        }}
                    >
                        <ListItem.Content>
                            <ListItem.Title>{lang === "en" ? country.name : country.name_ar}</ListItem.Title>
                        </ListItem.Content>
                        <ListItem.Chevron />
                    </ListItem>
                    <Input
                        inputContainerStyle={styles.input}
                        placeholder={lables['vehicle_nick_name']}
                        onChangeText={(e) => {
                            setName(e);
                        }}
                        value={name}
                    />
                    <View
                        style={{
                            display: 'flex',
                            flexDirection: 'row',
                        }}
                    >
                        <Input
                            containerStyle={{
                                width: 150,
                            }}
                            inputContainerStyle={styles.input}
                            placeholder={lables['plate_code']}
                            onChangeText={(e) => {
                                setPlateCode(e);
                            }}
                            value={plateCode}
                        />
                        <Input
                            containerStyle={{
                                width: Dimensions.get('screen').width - 150,
                            }}
                            inputContainerStyle={styles.input}
                            placeholder={lables['plate_number']}
                            onChangeText={(e) => {
                                setPlateNumber(e);
                            }}
                            value={plateNumber}
                        />
                    </View>
                    <ListItem
                        onPress={() => {
                            setShowDialog(true);
                        }}
                        containerStyle={{
                            borderWidth: 1,
                            borderRadius: 10,
                            margin: 10,
                        }}
                    >
                        <ListItem.Content>
                            <ListItem.Title>{lables['brand']}</ListItem.Title>
                        </ListItem.Content>
                        {
                            brand.id !== "" &&
                            <Avatar source={{ uri: brand.image }} />
                        }
                        <ListItem.Chevron />
                    </ListItem>
                </View>
                <Dialog
                    isVisible={showDialog}
                    overlayStyle={{
                        height: Dimensions.get('screen').height - 200,
                    }}
                >
                    <ScrollView>
                        {
                            brands.map((item, index) => {
                                return (
                                    <ListItem
                                        bottomDivider
                                        key={item.id}
                                        onPress={() => {
                                            setBrand(item);
                                        }}
                                    >
                                        <Avatar source={{ uri: item.image }} />
                                        <ListItem.Content>
                                            <ListItem.Title>{item.name}</ListItem.Title>
                                        </ListItem.Content>
                                        <ListItem.CheckBox
                                            onPress={() => {
                                                setBrand(item);
                                            }}
                                            checked={brand.id === item.id ? true : false}
                                            checkedIcon={
                                                <Icon name='checkbox-outline' size={22} />
                                            }
                                            uncheckedIcon={
                                                <Icon name='square-outline' size={22} />
                                            }
                                        />
                                    </ListItem>
                                );
                            })
                        }
                    </ScrollView>
                    <Button
                        title={lables['select']}
                        onPress={() => {
                            setShowDialog(false);
                        }}
                    />
                </Dialog>
                <Dialog
                    isVisible={showCountryDialog}
                    overlayStyle={{
                        height: Dimensions.get('screen').height - 350,
                    }}
                >
                    <ScrollView>
                        {
                            countries.map((item) => {
                                return (
                                    <ListItem
                                        bottomDivider
                                        key={item.code}
                                        onPress={() => {
                                            setCountry(item);
                                        }}
                                    >
                                        <ListItem.Content>
                                            <ListItem.Title>{lang === "en" ? item.name : item.name_ar}</ListItem.Title>
                                        </ListItem.Content>
                                        <ListItem.CheckBox
                                            onPress={() => {
                                                setBrand(item);
                                            }}
                                            checked={item.code === country.code ? true : false}
                                            checkedIcon={
                                                <Icon name='checkbox-outline' size={22} />
                                            }
                                            uncheckedIcon={
                                                <Icon name='square-outline' size={22} />
                                            }
                                        />
                                    </ListItem>
                                );
                            })
                        }
                    </ScrollView>
                    <Button
                        title={lables['select']}
                        onPress={() => {
                            setShowCountryDialog(false);
                        }}
                    />
                </Dialog>
                <Button
                    loading={loading}
                    title={lables['save']}
                    buttonStyle={{
                        margin: 30,
                    }}
                    onPress={() => {
                        let data = {
                            plate_code: plateCode,
                            plate_number: plateNumber,
                            brand: brand.id,
                            uid: user.id,
                            name: name,
                            country: country.code,
                        }
                        setLoading(true);
                        addVehicle(data)
                            .then((res) => {
                                setLoading(false);
                                props.navigation.navigate('Home');
                            })
                            .catch(() => {
                                setLoading(false);
                            })
                    }}
                />
            </ScrollView>
        </View>
    );
}
export default AddVehicle;
const styles = StyleSheet.create({
    input: {
        borderWidth: 1,
        borderRadius: 10,
        marginTop: 5,
        padding: 5,
    }
});