import React, { useEffect, useState } from 'react';
import { ScrollView, View, Alert, Image } from 'react-native';
import { Text, Input, Button, CheckBox } from '@rneui/themed';
import { register } from './../apis/apis';
import { setUser } from './../redux/reducer';
import { useStore } from 'react-redux';
import AsyncStorage from '@react-native-async-storage/async-storage';
import Icon from 'react-native-vector-icons/FontAwesome';
import messaging from '@react-native-firebase/messaging';
Icon.loadFont();
const SetupAccount = (props) => {
    const store = useStore();
    const lables = store.getState().app.trans;
    const [username, setUsername] = useState("");
    const [email, setEmail] = useState("");
    const [fcm, setFcm] = useState("");
    const [handicaped, setHandicaped] = useState(false);
    const [loading, setLoading] = useState(false);
    const user = {};//JSON.parse(props.route.params);

    useEffect(() => {
        props.navigation.setOptions({
            headerTitle: lables['register'],
            headerBackTitle: lables['back'],
            headerBackTitleVisible:false,
            headerShadowVisible: false,
        });
        messaging()
            .getToken()
            .then(token => {
                setFcm(token)
            });
    }, []);
    return (
        <View
            style={{
                flex: 1,
                padding: 15,
                backgroundColor: '#FFF'
            }}
        >
            <ScrollView>
                <View>
                    <Image source={require('./../assets/images/logowhite.png')}
                        style={{
                            width: 300,
                            height: 100,
                            alignSelf: 'center',
                            margin: 30,
                        }}
                    />
                    <Text
                        style={{
                            fontSize: 40,
                            fontWeight: 'bold',
                            textAlign: 'center',
                            color: '#28B3F3'
                        }}
                    >
                        {lables['hello']}
                    </Text>
                    <View>
                        <Input
                            value={username}
                            onChangeText={(e) => {
                                setUsername(e)
                            }}
                            inputStyle={{
                                fontSize: 20,
                                fontWeight: 'bold',
                            }}
                            containerStyle={{
                                paddingLeft: 0,
                                paddingRight: 0,
                            }}
                            placeholder={lables['full_name']}
                            inputContainerStyle={{
                                padding: 10,
                                borderRadius: 5,
                                borderWidth: 1,
                            }}
                            returnKeyType="done"
                        />
                        <Input
                            value={email}
                            onChangeText={(e) => {
                                setEmail(e)
                            }}
                            inputStyle={{
                                fontSize: 20,
                                fontWeight: 'bold',
                            }}
                            containerStyle={{
                                paddingLeft: 0,
                                paddingRight: 0,
                            }}
                            placeholder={lables['Email']}
                            inputContainerStyle={{
                                padding: 10,
                                borderRadius: 5,
                                borderWidth: 1,
                            }}
                            returnKeyType="done"
                        />
                    </View>
                    <Text
                        style={{
                            textAlign: 'center',
                            fontSize: 18,
                            fontWeight: '800'
                        }}
                    >{lables['Select_Handicap_Option']}</Text>
                    <Icon name='wheelchair'
                        style={{
                            alignSelf: 'center',
                            padding: 10,
                        }}
                        size={40}
                    />
                    <View
                        style={{
                            display: 'flex',
                            justifyContent: 'center',
                            flexDirection: 'row'
                        }}
                    >
                        <CheckBox
                            checked={!handicaped}
                            onPress={() => {
                                setHandicaped(false);
                            }}
                            checkedIcon="dot-circle-o"
                            uncheckedIcon="circle-o"
                            title={lables['no']}
                        />
                        <CheckBox
                            checked={handicaped}
                            onPress={() => {
                                setHandicaped(true);
                            }}
                            checkedIcon="dot-circle-o"
                            uncheckedIcon="circle-o"
                            title={lables['Yes']}
                        />
                    </View>
                    <Button
                        loading={loading}
                        title={lables['register']}
                        onPress={() => {
                            if (username.length !== 0 && email.length > 4) {
                                let data = {
                                    email: email,
                                    username: username,
                                    fuid: user.uid,
                                    phone: user.phoneNumber,
                                    handicaped: handicaped,
                                    fcm:fcm
                                }
                                register(data)
                                    .then((res) => {
                                        setLoading(false);
                                        if (res.code === 200) {
                                            AsyncStorage.setItem('_user', JSON.stringify(res.data));
                                            store.dispatch(setUser(res.data));
                                            props.navigation.navigate('AddVehicle');
                                        } else {
                                            setLoading(false);
                                            Alert.alert(res.msg);
                                        }
                                    })
                                    .catch((e) => {
                                        setLoading(false);
                                        Alert.alert(res.msg);
                                    })
                            }
                        }}
                    />
                </View>
            </ScrollView>
        </View>
    );
}

export default SetupAccount;