import React, { useEffect, useState } from 'react';
import { ScrollView, View, Image, Dimensions, Alert } from 'react-native';
import { Text, Input, Button, CheckBox } from '@rneui/themed';
import { useStore } from 'react-redux';
import { Pressable } from 'react-native';
import Icon from 'react-native-vector-icons/Ionicons';
import { checkUser } from './../apis/apis';
import Icon2 from 'react-native-vector-icons/FontAwesome';
import { register } from './../apis/apis';
import { setUser } from './../redux/reducer';
import messaging from '@react-native-firebase/messaging';
import AsyncStorage from '@react-native-async-storage/async-storage';

const Register = (props) => {
    const [phone, setPhone] = useState("");
    const [email, setEmail] = useState("");
    const [name, setName] = useState("");
    const [password, setPassword] = useState("");
    const [showPassword, setShowPassword] = useState(false);
    const [loading, setLoading] = useState(false);
    const store = useStore();
    const lables = store.getState().app.trans;
    const [handicaped, setHandicaped] = useState(false);
    const [fcm, setFcm] = useState("");
    useEffect(() => {
        props.navigation.setOptions({
            headerTitle: lables['register'],
            headerBackTitle: lables['back'],
            headerBackTitleVisible: false,
            headerShadowVisible: false,
        });
        messaging()
            .getToken()
            .then(token => {
                setFcm(token)
            });
    }, []);

    const handleRegister = async () => {
        // 
        const emailPattern = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}/g;
        if (email.match(emailPattern)) {
            setLoading(true);
            let res = await checkUser({ email: email });
            if (!res.data) {
                let userData = {
                    email: email,
                    phone: phone,
                    password: password,
                    fuid: '',
                    handicaped: handicaped,
                    password: password,
                    fcm: fcm,
                    username: name
                }
                let user = await register(userData);
                setLoading(false);
                if (user.code === 200) {
                    AsyncStorage.setItem('_user', JSON.stringify(user.data.data));
                    store.dispatch(setUser(user.data.data));
                    props.navigation.navigate('AddVehicle');
                } else {

                    setLoading(false);
                    Alert.alert(lables['missing_data'], lables['enter_all_feilds']);
                }
            } else {
                setLoading(false);
                Alert.alert(lables['acc_exist'], lables['acc_exist_text']);
            }
        }else{
            Alert.alert(lables['missing_data'], lables['enter_all_feilds']);
        }

    }
    return (
        <View
            style={{
                flex: 1,
                padding: 15,
                backgroundColor: '#FFF'
            }}
        >
            <ScrollView>
                <View>
                    <Image source={require('./../assets/images/logowhite.png')}
                        style={{
                            width: 150,
                            height: 50,
                            alignSelf: 'center',
                            // margin: 30,
                        }}
                    />
                    <Text
                        style={{
                            fontSize: 20,
                            fontWeight: 'bold',
                            textAlign: 'center',
                            color: '#28B3F3',

                        }}
                    >{lables['signup']}</Text>
                    <View
                        style={{

                            marginTop: 20,
                        }}
                    >

                        <Input
                            value={name}
                            onChangeText={(e) => {
                                setName(e)
                            }}
                            inputStyle={{
                                fontSize: 20,
                                fontWeight: 'bold',
                                marginLeft: 10,
                                marginRight: 10,
                            }}
                            inputContainerStyle={{
                                borderWidth: 1,
                                borderRadius: 5,
                                padding: 5,
                            }}
                            placeholder={lables['full_name']}
                        />
                        <Input
                            value={phone}
                            onChangeText={(e) => {
                                setPhone(e)
                            }}
                            inputStyle={{
                                fontSize: 20,
                                fontWeight: 'bold',
                                marginLeft: 10,
                                marginRight: 10,
                            }}
                            inputContainerStyle={{
                                borderWidth: 1,
                                borderRadius: 5,
                                padding: 5,
                            }}
                            placeholder={lables['mobile']}
                            keyboardType="number-pad"
                            returnKeyType="done"
                        />
                        <Input
                            value={email}
                            onChangeText={(e) => {
                                setEmail(e)
                            }}
                            inputStyle={{
                                fontSize: 20,
                                fontWeight: 'bold',
                                marginLeft: 10,
                                marginRight: 10,
                            }}
                            inputContainerStyle={{
                                borderWidth: 1,
                                borderRadius: 5,
                                padding: 5,
                            }}
                            placeholder={lables['Email']}
                        />
                        <Input
                            rightIcon={
                                <Pressable
                                    onPress={() => {
                                        setShowPassword(!showPassword);
                                    }}
                                >
                                    <Icon name={showPassword ? 'eye-outline' : 'eye-off-outline'} size={30} />
                                </Pressable>
                            }
                            value={password}
                            onChangeText={(e) => {
                                setPassword(e)
                            }}
                            inputStyle={{
                                fontSize: 20,
                                fontWeight: 'bold',
                                marginLeft: 10,
                                marginRight: 10,
                            }}
                            inputContainerStyle={{
                                borderWidth: 1,
                                borderRadius: 5,
                                padding: 5,
                            }}
                            placeholder={lables['password']}
                            secureTextEntry={!showPassword}
                        />
                        <Text
                            style={{
                                textAlign: 'center',
                                fontSize: 18,
                                fontWeight: '800'
                            }}
                        >{lables['Select_Handicap_Option']}</Text>
                        <Icon2 name='wheelchair'
                            style={{
                                alignSelf: 'center',
                                padding: 10,
                            }}
                            size={40}
                        />
                        <View
                            style={{
                                display: 'flex',
                                justifyContent: 'center',
                                flexDirection: 'row'
                            }}
                        >
                            <CheckBox
                                checked={!handicaped}
                                onPress={() => {
                                    setHandicaped(false);
                                }}
                                checkedIcon="dot-circle-o"
                                uncheckedIcon="circle-o"
                                title={lables['no']}
                            />
                            <CheckBox
                                checked={handicaped}
                                onPress={() => {
                                    setHandicaped(true);
                                }}
                                checkedIcon="dot-circle-o"
                                uncheckedIcon="circle-o"
                                title={lables['Yes']}
                            />
                        </View>
                    </View>
                    <Button
                        loading={loading}
                        title={lables['signup']}
                        onPress={() => {
                            handleRegister();
                        }}
                    />
                    <Pressable
                        onPress={() => {
                            props.navigation.navigate('Login')
                        }}
                    >
                        <Text
                            style={{
                                padding: 10,
                                fontSize: 16,
                                fontWeight: 'bold',
                                textDecorationLine: 'underline'
                            }}
                        >{lables['accout_exist_login']}</Text>
                    </Pressable>
                </View>
            </ScrollView>
        </View>
    );
}

export default Register;