import React, { useRef, useState, useEffect } from 'react';
import { View, Image, Dimensions } from 'react-native';
import Carousel, { Pagination } from 'react-native-snap-carousel';
const Sliders = () => {
    const sliders = ['https://images.unsplash.com/photo-1621647017805-7d08d0a38c8a?ixlib=rb-4.0.3&ixid=MnwxMjA3fDB8MHxzZWFyY2h8NXx8a3V3YWl0fGVufDB8fDB8fA%3D%3D&auto=format&fit=crop&w=900&q=60', 'https://images.unsplash.com/photo-1558634742-56096b49522b?ixlib=rb-4.0.3&ixid=MnwxMjA3fDB8MHxzZWFyY2h8Mnx8a3V3YWl0JTIwY2l0eXxlbnwwfHwwfHw%3D&auto=format&fit=crop&w=900&q=60', 'https://images.unsplash.com/photo-1536099629323-44806c1ea264?ixlib=rb-4.0.3&ixid=MnwxMjA3fDB8MHxzZWFyY2h8MjN8fHRyYWZmaWN8ZW58MHx8MHx8&auto=format&fit=crop&w=900&q=60'];
    const [activeIndex, setActiveIndex] = useState(0);
    const ref = useRef();
    const renderItem = (item) => {
        return (
            <View>
                <Image
                    source={{ uri: item.item }}
                    style={{
                        width: Dimensions.get('screen').width - 20,
                        height: Dimensions.get('screen').width > 600 ? 230 : 170,
                        borderRadius: 10,
                    }}
                />
            </View>
        );
    }
    return (
        <View>
            <Carousel
                ref={ref}
                data={sliders}
                renderItem={renderItem}
                sliderWidth={Dimensions.get('screen').width}
                itemWidth={Dimensions.get('screen').width - 20}
                hasParallaxImages={true}
                inactiveSlideScale={0.94}
                inactiveSlideOpacity={0.7}
                loop={true}
                loopClonesPerSide={2}
                autoplay={true}
                autoplayDelay={500}
                autoplayInterval={3000}
                onSnapToItem={(index) => {
                    setActiveIndex(index);
                }}
            />
            <Pagination
                dotsLength={sliders.length}
                activeDotIndex={activeIndex}
                dotColor="#FFF"
                inactiveDotColor="#FFF"
                containerStyle={{
                    paddingTop: 19,
                    paddingBottom: -0,
                    marginTop: 4,
                }}
                dotElement={
                    <View
                        style={{
                            height: 3,
                            width: 20,
                            borderColor: '#000',
                            backgroundColor: '#000',
                            margin: 2,
                        }}
                    >
                    </View>
                }
                inactiveDotElement={
                    <View
                        style={{
                            height: 3,
                            width: 20,
                            borderWidth: 0.5,
                            margin: 2,
                            borderColor: '#CCC',
                            backgroundColor: '#CCC'
                        }}
                    ></View>
                }
                inactiveDotOpacity={1}
                inactiveDotScale={0.5}
                carouselRef={ref}
            />
        </View>
    );
}

export default Sliders;