import React, { useEffect, useState } from 'react';
import { ScrollView, View, Alert } from 'react-native';
import { Text, Input, Button } from '@rneui/themed';
import auth from '@react-native-firebase/auth';
import { useStore } from 'react-redux';
import { checkUser } from './../apis/apis';
import { setUser } from './../redux/reducer';
import AsyncStorage from '@react-native-async-storage/async-storage';
const OTP = (props) => {
    const store = useStore();
    const lables = store.getState().app.trans;
    const phone = props.route.params;
    const [confirm, setConfirm] = useState(null);
    const [code, setCode] = useState("");
    const [loading, setLoading] = useState(false);
    useEffect(() => {
        signInWithPhoneNumber('+965 ' + phone);
        props.navigation.setOptions({
            headerTitle: lables['register'],
            headerBackTitle: lables['back'],
            headerBackTitleVisible:false,
            headerShadowVisible: false,
        });
    }, []);
    async function signInWithPhoneNumber(phoneNumber) {
        const confirmation = await auth().signInWithPhoneNumber(phoneNumber);
        setConfirm(confirmation);
    }
    async function confirmCode() {
        setLoading(true);
        try {
            const res = await confirm.confirm(code);
            setLoading(false);
            checkUserExistence(res);
        } catch (error) {
            console.log(error);
            setLoading(false);
            Alert.alert(lables['Invalid_otp'], lables['Invalid_otp_message']);

        }
    }
    const checkUserExistence = (fres) => {
        let userPhone = '+965' + phone;
        checkUser(userPhone)
            .then((res) => {
                console.log(res.data);
                if (res.data) {
                    AsyncStorage.setItem('_user', JSON.stringify(res));
                    store.dispatch(setUser(res));
                    props.navigation.navigate('Home');
                } else {
                    props.navigation.navigate('SetupAccount', JSON.stringify(fres.user));
                }
            })
            .catch(e => {
                console.log(e);
            });
    }
    return (
        <View
            style={{
                flex: 1,
                padding: 15,
                backgroundColor: '#FFF'
            }}
        >
            <ScrollView>
                <View>
                    <Text
                        style={{
                            fontSize: 32,
                            fontWeight: 'bold',
                            textAlign: 'center'
                        }}
                    >{lables['Enter_otp']}</Text>
                    <Text
                        style={{
                            fontSize: 32,
                            fontWeight: 'bold',
                            textAlign: 'center',
                            padding: 10,
                        }}
                    >{phone} </Text>
                    <Input
                        value={code}
                        onChangeText={(e) => {
                            setCode(e);
                        }}
                        inputContainerStyle={{
                            borderWidth: 1,
                            borderRadius: 5,
                        }}
                        placeholder="******"
                        inputStyle={{
                            textAlign: 'center',
                            letterSpacing: 30,
                            padding: 20,
                        }}
                        maxLength={6}
                    />
                    <Button
                        title={lables['confirm']}
                        loading={loading}
                        onPress={() => {
                            confirmCode();
                        }}
                    />
                </View>
            </ScrollView>
        </View>
    );
}

export default OTP;