import React, { useEffect } from 'react';
import { StatusBar, View, Image, I18nManager } from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { getTranslations } from './../apis/apis';
import { setTrans, setUser,setLinks } from './../redux/reducer';
import { useStore } from 'react-redux';
import { loadUser } from './../apis/apis';
const Landing = (props) => {
    const store = useStore();
    const lang = I18nManager.isRTL ? 'ar' : 'en';
    useEffect(() => {
        // AsyncStorage.removeItem('_user');
        getTranslations(lang)
            .then(async (data) => {
                store.dispatch(setTrans(data.data.lables));
                store.dispatch(setLinks(data.data.links));
                
                let user = await AsyncStorage.getItem('_user');
                if (user !== null) {
                    user = JSON.parse(user);
                    const dbUser = await loadUser(user.id);
                    store.dispatch(setUser(dbUser.data));
                    setTimeout(() => {
                        props.navigation.navigate('Home');
                    }, 2000)
                } else {
                    setTimeout(() => {
                        props.navigation.navigate('Welcome');
                    }, 2000)
                }
            })

    }, []);
    return (
        <View
            style={{
                flex: 1,
                backgroundColor: '#FFF'
            }}
        >
            <StatusBar
                barStyle="dark-content"
            />
            <View
                style={{
                    flex: 1,
                    justifyContent: 'center',
                    alignItems: 'center'
                }}
            >
                <Image source={require('./../assets/images/logo.gif')}
                    style={{
                        width: 300,
                        height: 100,
                    }}
                />
            </View>
            {/* <Lottie
                source={require('./../animations/landing.json')}
                loop={true}
                autoPlay={true}
            /> */}
        </View>
    );
}

export default Landing;