import { ListItem, Text } from '@rneui/themed';
import React, { useState, useEffect } from 'react';
import { View, ScrollView, I18nManager, ActivityIndicator, Dimensions } from 'react-native';
import { useStore } from 'react-redux';
import Icon from 'react-native-vector-icons/Ionicons';
import { getCurrentParkings } from '../apis/apis';
const CurrentBookings = (props) => {
    const store = useStore();
    const lables = store.getState().app.trans;
    const user = store.getState().app.user;
    const lang = I18nManager.isRTL ? 'ar' : 'en';
    let params = props.route.params !== undefined ? props.route.params.data : [];
    const [currentParkings, setCurrentParkings] = useState(params);
    const [loading, setLoading] = useState(true);
    useEffect(() => {
        props.navigation.setOptions({
            headerTitle: lables['current_parkings'],
            headerBackTitle: lables['back'],
            headerBackTitleVisible:false,
            headerShadowVisible: false,
            headerTintColor: '#FFF',
            headerStyle: {
                backgroundColor: '#28B4F2'
            },
        });
        getCurrentParkings(user.id)
            .then((res) => {
                if (res.code === 200) {
                    setCurrentParkings(res.data.data);
                }
                setLoading(false);
            })
            .catch(e => {
                setLoading(false);
            });
    }, []);
    return (
        <View
            style={{
                flex: 1,
                backgroundColor: '#FFF',
            }}
        >
            {
                loading &&
                <View
                    style={{
                        display: 'flex',
                        justifyContent: 'center',
                        alignItems: 'center',
                        height: Dimensions.get('screen').height - 150,
                    }}
                >
                    <ActivityIndicator />
                </View>
            }
            {
                !loading && currentParkings.length === 0 &&
                <View
                    style={{
                        display: 'flex',
                        justifyContent: 'center',
                        alignItems: 'center',
                        height: Dimensions.get('screen').height - 150,
                    }}
                >
                    <Icon name='alert-circle' size={60} color={"#28B3F3"} />
                    <Text>{lables['no_records']}</Text>
                </View>
            }

            <ScrollView>

                <View
                    style={{
                        marginTop:30,
                    }}
                >
                    {/* <Text
                        style={{
                            fontSize: 30,
                            fontWeight: '600',
                            padding: 15,
                        }}
                    >{lables['your_current_parkings']}</Text> */}
                    {
                        currentParkings.map((item) => {
                            return (
                                <View key={item.id}>
                                    <ListItem
                                        onPress={() => {
                                            props.navigation.navigate('ViewParking', item);
                                        }}
                                        containerStyle={{
                                            backgroundColor: '#FFF',
                                            borderRadius: 10,
                                            shadowColor: "#28B3F3",
                                            shadowOffset: {
                                                width: 0,
                                                height: 1,
                                            },
                                            shadowOpacity: 0.25,
                                            shadowRadius: 3.50,
                                            elevation: 2,
                                            margin: 15,
                                            marginTop: 10,
                                            marginBottom: 10,
                                        }}
                                    >
                                        <Icon name='location-outline' size={30} />
                                        <ListItem.Content>
                                            <ListItem.Title>{lang === "en" ? item.location_name : item.location_name_ar}</ListItem.Title>
                                            <ListItem.Subtitle>{item.block + ',' + item.level}</ListItem.Subtitle>
                                        </ListItem.Content>
                                        <View>
                                            {/* <Text>{item.start_time + ' - ' + item.end_time}</Text> */}
                                            <Text>{item.start_time}</Text>
                                            <Text>{item.hours + ' ' + lables['hours']}</Text>
                                        </View>
                                    </ListItem>
                                    
                                </View>
                            );
                        })
                    }
                </View>
            </ScrollView>
        </View>
    );
}

export default CurrentBookings;