import { Button, Input, Text, ListItem } from '@rneui/themed';
import React, { useState, useRef, useEffect } from 'react';
import { View, ScrollView, Pressable, StyleSheet, Dimensions, I18nManager, RefreshControl } from 'react-native';
import Icon from 'react-native-vector-icons/Ionicons';
import RBSheet from "react-native-raw-bottom-sheet";
import { useStore } from 'react-redux';
import { setWallet } from './../redux/reducer';
import { getLatestTransactions } from './../apis/apis';
import { useFocusEffect } from '@react-navigation/native';
const Wallet = (props) => {
    const store = useStore();
    const refRBSheet = useRef();
    const [wallet, setUserWallet] = useState(store.getState().app.wallet);
    const lables = store.getState().app.trans;
    const [amount, setAmount] = useState('');
    const [loading, setLoading] = useState(false);
    const [transactions, setTransactions] = useState([]);
    const lang = I18nManager.isRTL ? 'ar' : 'en';
    const user = store.getState().app.user;

    useFocusEffect(() => {
        props.navigation.getParent().setOptions({
            headerTitle: lables['wallet']
        });
    });
    useEffect(() => {
        loadTransactions();
        store.subscribe(() => {
            setUserWallet(store.getState().app.wallet);
        });
    }, []);
    const loadTransactions = async () => {
        const payments = await getLatestTransactions(user.id);
        setTransactions(payments.data);
        setLoading(false);
    }
    return (
        <View
            style={{
                flex: 1,
                backgroundColor: '#FFF',
            }}
        >
            <ScrollView showsVerticalScrollIndicator={false}

                refreshControl={
                    <RefreshControl
                        refreshing={loading}
                        onRefresh={() => {
                            setLoading(true);
                            loadTransactions();
                        }}
                    />
                }
            >
                <View>
                    <Text
                        style={{
                            fontSize: 30,
                            padding: 20,
                            fontWeight: '600'
                        }}
                    >{lables['wallet']}</Text>
                    <ListItem
                        containerStyle={{
                            backgroundColor: '#ededed',
                            margin: 15,
                            borderRadius: 7,
                        }}
                    >
                        <ListItem.Content>
                            <ListItem.Title>{lables['balance']}</ListItem.Title>
                            <ListItem.Subtitle
                                style={{
                                    fontWeight: 'bold'
                                }}
                            >KD {wallet?.balance.toFixed(3)}</ListItem.Subtitle>
                        </ListItem.Content>
                        <Button
                            onPress={() => {
                                refRBSheet.current.open();
                            }}
                            iconPosition="left"
                            icon={
                                <Icon name='add' color={"#FFF"} size={32} style={{ marginRight: 10 }} />
                            }
                            buttonStyle={{
                                borderRadius: 30,

                            }}
                        >{lables['recharge']}</Button>
                    </ListItem>
                    <ListItem>
                        <Icon name='time-outline' size={30} />
                        <ListItem.Content>
                            <ListItem.Title
                                style={{
                                    fontWeight: 'bold'
                                }}
                            >{lables['recent_payments']}</ListItem.Title>
                        </ListItem.Content>
                    </ListItem>
                    <View
                        style={{
                            padding: 10,
                        }}
                    >
                        {
                            transactions.length === 0 &&
                            <View
                                style={{
                                    alignItems: 'center',
                                    padding: 10,
                                }}
                            >
                                <Icon name='alert-circle' size={60} color={"red"} />
                                <Text>{lables['no_records']}</Text>
                            </View>
                        }
                        {
                            transactions.map((item, index) => {
                                return (
                                    <ListItem
                                        onPress={() => {
                                            props.navigation.navigate('viewPayment', item)
                                        }}
                                        bottomDivider
                                        key={index}
                                        containerStyle={{
                                            margin: 5,
                                            backgroundColor: '#FFF',
                                            shadowColor: 'rgba(31, 38, 135, 0.37)',
                                            shadowOffset: { width: 0, height: 8 },
                                            shadowRadius: 32,
                                            shadowOpacity: 1,
                                            elevation: 8,
                                            borderRadius: 10,
                                            borderWidth: 1,
                                            borderColor: 'rgba(255, 255, 255, 0.18)',
                                            backdropFilter: 'blur(4px)',
                                        }}
                                    >
                                        <ListItem.Content>
                                            <ListItem.Title style={{ fontWeight: 'bold', fontSize: 22 }}>KWD {item.amount.toFixed(3)}</ListItem.Title>
                                            <ListItem.Subtitle>{new Date(item.updated_at).toDateString()}</ListItem.Subtitle>
                                        </ListItem.Content>
                                        <View>
                                            <Icon
                                                name={item.payment_status === "success" ? 'checkmark-circle' : 'close-circle'}
                                                color={item.payment_status === "success" ? 'green' : 'red'}
                                                size={34}
                                            />
                                        </View>
                                        <Text>
                                            {lables[item.payment_status]}
                                        </Text>
                                    </ListItem>
                                );
                            })
                        }
                    </View>
                    <RBSheet
                        height={600}
                        ref={refRBSheet}
                        closeOnDragDown={true}
                        closeOnPressMask={false}
                        customStyles={{
                            wrapper: {
                                backgroundColor: "rgba(0,0,0,0.6)",
                            },
                            draggableIcon: {
                                backgroundColor: "#000"
                            },
                            container: {
                                borderTopLeftRadius: 30,
                                borderTopRightRadius: 30,
                                backgroundColor: '#FFF'
                            }
                        }}
                    >
                        <View
                            style={{
                                padding: 20,
                            }}
                        >
                            <ListItem>
                                <ListItem.Content>
                                    <ListItem.Title
                                        style={{
                                            fontWeight: 'bold',
                                            fontSize: 26,
                                        }}
                                    >{lables['recharge']}</ListItem.Title>
                                </ListItem.Content>
                                <Icon name='close' size={30}
                                    onPress={() => {
                                        refRBSheet.current.close();
                                    }}
                                />
                            </ListItem>
                            <View
                                style={{
                                    borderWidth: 1,
                                    borderColor: '#CCC',
                                    borderRadius: 5,
                                    padding: 2,
                                }}
                            >
                                <ListItem>
                                    <Icon name='card-outline' size={20} />
                                    <ListItem.Content>
                                        <ListItem.Title
                                            style={{
                                                fontWeight: 'bold',
                                                fontSize: 16,
                                            }}
                                        >{lables['amount']}</ListItem.Title>
                                    </ListItem.Content>

                                </ListItem>
                                <ScrollView
                                    horizontal={true}
                                    showsHorizontalScrollIndicator={false}
                                >
                                    <Pressable
                                        style={amount === 3 ? styles.activeCurrency : styles.inactiveCurrency}
                                        onPress={() => {
                                            setAmount(3);
                                        }}
                                    >
                                        <Text

                                            style={amount === 3 ? styles.activeCurrencyText : styles.inactiveCurrencyText}
                                        >KD 3</Text>
                                    </Pressable>
                                    <Pressable
                                        style={amount === 5 ? styles.activeCurrency : styles.inactiveCurrency}
                                        onPress={() => {
                                            setAmount(5);
                                        }}
                                    >
                                        <Text
                                            style={amount === 5 ? styles.activeCurrencyText : styles.inactiveCurrencyText}
                                        >KD 5</Text>
                                    </Pressable>
                                    <Pressable
                                        style={amount === 10 ? styles.activeCurrency : styles.inactiveCurrency}
                                        onPress={() => {
                                            setAmount(10);
                                        }}
                                    >
                                        <Text
                                            style={amount === 10 ? styles.activeCurrencyText : styles.inactiveCurrencyText}
                                        >KD 10</Text>
                                    </Pressable>
                                    <Pressable
                                        style={amount === 20 ? styles.activeCurrency : styles.inactiveCurrency}
                                        onPress={() => {
                                            setAmount(20);
                                        }}
                                    >
                                        <Text
                                            style={amount === 20 ? styles.activeCurrencyText : styles.inactiveCurrencyText}
                                        >KD 20</Text>
                                    </Pressable>
                                </ScrollView>
                                <Input
                                    keyboardType="number-pad"
                                    returnKeyType="done"
                                    placeholder={lables['enter_amount']}
                                    inputContainerStyle={{
                                        borderWidth: 1,
                                        borderRadius: 10,
                                        backgroundColor: '#FFF',
                                        marginTop: 30,
                                        padding: 6,
                                        paddingLeft: 20,
                                        paddingRight: 20,
                                    }}
                                    onChangeText={(e) => {
                                        setAmount(parseFloat(e));
                                    }}
                                    value={amount+''}
                                />
                                 <Input
                                    keyboardType="number-pad"
                                    returnKeyType="done"
                                    placeholder={lables['enter_cupon']}
                                    inputContainerStyle={{
                                        borderWidth: 1,
                                        borderRadius: 10,
                                        backgroundColor: '#FFF',
                                        padding: 6,
                                        paddingLeft: 20,
                                        paddingRight: 20,
                                    }}
                                    onChangeText={(e) => {
                                        // setAmount(parseFloat(e));
                                    }}
                                    // value={amount}
                                />
                            </View>

                            <Button
                                onPress={() => {
                                    refRBSheet.current.close()
                                    props.navigation.navigate('recharge', amount);
                                }}
                                buttonStyle={{
                                    borderRadius: 30,
                                    marginTop: 20,
                                }}
                            >{lables['recharge']}</Button>
                        </View>
                    </RBSheet>
                </View>
            </ScrollView>
        </View>
    );
}

export default Wallet;
const styles = StyleSheet.create({
    pressable: {
        borderRadius: 10,
        width: Dimensions.get('screen').width / 2.7,
        margin: 10,
    },
    amount: {
        fontSize: 30,
        color: '#FFF',
        fontWeight: 'bold'
    },
    currency: {
        fontWeight: 'bold',
        fontSize: 16,
        color: '#FFF'
    },
    inactiveCurrency: {
        padding: 10,
        borderWidth: 1,
        borderRadius: 30,
        paddingLeft: 20,
        paddingRight: 20,
        margin: 10,
    },
    activeCurrency: {
        padding: 10,
        borderWidth: 1,
        borderRadius: 30,
        paddingLeft: 20,
        paddingRight: 20,
        margin: 10,
        backgroundColor: '#28B3F3',
        borderColor: '#FFF'
    },
    activeCurrencyText: {
        color: '#FFF',
        fontWeight: 'bold'
    },
    inactiveCurrencyText: {
        fontWeight: 'bold'
    }
});