import React, { useEffect, useState } from 'react';
import { View, ScrollView, StyleSheet } from 'react-native';
import { useStore } from 'react-redux';
import { Avatar, ListItem, Text, Input, Button } from '@rneui/themed';
import Icon from 'react-native-vector-icons/Ionicons';
import { useFocusEffect } from '@react-navigation/native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import RNRestart from 'react-native-restart';
import { resetPassword } from './../apis/apis';
import { Dialog } from '@rneui/themed';
const Profile = (props) => {
    useFocusEffect(() => {
        props.navigation.getParent().setOptions({
            headerTitle: lables['profile']
        });
    });
    const store = useStore();
    const user = store.getState().app.user;
    const lables = store.getState().app.trans;
    const [showDialog, setShowDialog] = useState(false);
    const [loading, setLoading] = useState(false);
    const [password, setPassword] = useState(false);
    const updatePassword = async () => {
        try {
            setLoading(true);
            let data = {
                uid: user.id,
                password: password,
            }
            const res = await resetPassword(data);
            setLoading(false);
            RNRestart.restart();
        } catch (error) {
            setLoading(false);
        }
    }
    return (
        <View
            style={{
                flex: 1,
                backgroundColor: '#FFF',
                padding: 15,
            }}
        >
            <ScrollView showsVerticalScrollIndicator={false}>
                <View>
                    <Avatar
                        containerStyle={{
                            alignSelf: 'center',
                        }}
                        size={"xlarge"}
                        rounded
                        source={{
                            uri: user.avatar ? user.avatar : "https://www.w3schools.com/w3images/avatar3.png",
                        }}
                    />
                    <ListItem containerStyle={style.containerStyle}>
                        <Icon name='person-outline' size={22} />
                        <ListItem.Content>
                            <ListItem.Title>{user.name}</ListItem.Title>
                        </ListItem.Content>
                    </ListItem>
                    <ListItem containerStyle={style.containerStyle}>
                        <Icon name='mail-outline' size={22} />
                        <ListItem.Content>
                            <ListItem.Title>{user.email}</ListItem.Title>
                        </ListItem.Content>
                    </ListItem>
                    <ListItem containerStyle={style.containerStyle}>
                        <Icon name='call-outline' size={22} />
                        <ListItem.Content>
                            <ListItem.Title>{user.phone}</ListItem.Title>
                        </ListItem.Content>
                    </ListItem>

                    <ListItem containerStyle={style.containerStyle}
                        onPress={() => {
                            props.navigation.navigate('MyDevices');
                        }}
                    >
                        <Icon name='heart-outline' size={22} />
                        <ListItem.Content>
                            <ListItem.Title>{lables['my_devices']}</ListItem.Title>
                        </ListItem.Content>
                        <ListItem.Chevron />
                    </ListItem>

                    <ListItem containerStyle={style.containerStyle}
                        onPress={() => {
                            props.navigation.navigate('MyParkings');
                        }}
                    >
                        <Icon name='calendar-outline' size={22} />
                        <ListItem.Content>
                            <ListItem.Title>{lables['history']}</ListItem.Title>
                        </ListItem.Content>
                        <ListItem.Chevron />
                    </ListItem>
                    <ListItem containerStyle={style.containerStyle}
                        onPress={() => {
                            props.navigation.navigate('notifications');
                        }}
                    >
                        <Icon name='notifications-outline' size={22} />
                        <ListItem.Content>
                            <ListItem.Title>{lables['notifications']}</ListItem.Title>
                        </ListItem.Content>
                        <ListItem.Chevron />
                    </ListItem>
                    {
                        user.role === "admin" &&
                        <ListItem containerStyle={style.containerStyle}
                            onPress={() => {
                                props.navigation.navigate('admin');
                            }}
                        >
                            <Icon name='options-outline' size={22} />
                            <ListItem.Content>
                                <ListItem.Title>{lables['admin']}</ListItem.Title>
                            </ListItem.Content>
                            <ListItem.Chevron />
                        </ListItem>
                    }

                    <ListItem containerStyle={style.containerStyle}
                        onPress={() => {
                            setShowDialog(true);
                        }}
                    >
                        <Icon name='lock-closed-outline' size={26} color="#000" />
                        <ListItem.Content>
                            <ListItem.Title>Reset Password</ListItem.Title>
                        </ListItem.Content>
                        <ListItem.Chevron color={"#000"} />
                    </ListItem>
                    <ListItem containerStyle={style.containerStyle}
                        onPress={() => {
                            AsyncStorage.removeItem('_user');
                            RNRestart.restart();
                        }}
                    >
                        <Icon name='trash-outline' size={26} color="#000" />
                        <ListItem.Content>
                            <ListItem.Title>{lables['delete_account']}</ListItem.Title>
                        </ListItem.Content>
                        <ListItem.Chevron color={"#000"} />
                    </ListItem>
                </View>
            </ScrollView>
            <Dialog
                isVisible={showDialog}
            >
                <Input
                    inputContainerStyle={{
                        borderWidth: 1,
                        borderRadius: 10,
                        paddingHorizontal: 10,
                        paddingVertical: 4
                    }}
                    placeholder='Enter New Password'
                    onChangeText={(e)=>{
                        setPassword(e);
                    }}
                />
                <View style={{
                    display: 'flex',
                    flexDirection: 'row',
                    justifyContent: 'space-evenly'
                }}>
                    <Button
                        loading={loading}
                        onPress={() => {
                            updatePassword();
                        }}
                    >Update</Button>
                    <Button
                        onPress={() => {
                            setShowDialog(false);
                        }}
                    >Cancel</Button>
                </View>
            </Dialog>
        </View>
    );
}

export default Profile;
const style = StyleSheet.create({
    containerStyle: {
        backgroundColor: '#FFF',
        borderRadius: 10,
        shadowColor: "#28B3F3",
        shadowOffset: {
            width: 0,
            height: 1,
        },
        shadowOpacity: 0.25,
        shadowRadius: 3.50,
        elevation: 2,
        margin: 15,
        marginTop: 10,
        marginBottom: 10,
    },
});